// === Tab: mySketch ===
//p5.js shader basic structure ref from https://www.openprocessing.org/sketch/920144

let theShader;
let timer = 0;
let mX = my = 0;
let nX = nY = 0;
function preload(){
	theShader = createShader(vert, frag)
}

function setup() {
	createCanvas(1112, 834, WEBGL);
	noStroke()
	background(0);
	mX = width / 2;
	mY = height / 2;
	nX = width / 2;
	nY = height / 2;
}

function draw() {
	if (timer > 30){
	  mX = random(width);
	  mY = random(height);
		timer = 0;
	}
	if (nX > mX) nX-=4;
	if (nY > mY) nY-=4;
	if (nX < mX) nX+=4;
	if (nY < mY) nY+=4;

	shader(theShader)
	theShader.setUniform('u_resolution',[width/1000,height/1000])
	theShader.setUniform('u_time',millis()/1000)
	theShader.setUniform('u_mouse',[nX/width,nY/height])
	rect(0,0,width,height)
	fill(255, 40);
	ellipse(mX, mY, 40, 30);
	timer++;
}

// === Tab: frag ===
const frag = `
	#ifdef GL_ES
	precision mediump float;
	#endif

	uniform vec2 u_resolution;
	uniform vec2 u_mouse;
	uniform float u_time;

	varying vec2 vTexCoord;

	void main(){
		vec2 st = vTexCoord.xy /u_resolution.xy;
		st.y = 1.0 - st.y;
		vec3 color = vec3(st.x,st.y,1.0);
		float d = distance(u_mouse,st);
		color*=1.-d;
		gl_FragColor= vec4(color,1.0);
	}
`

// === Tab: vert ===
const vert = `
	attribute vec3 aPosition;
	attribute vec2 aTexCoord;

	varying vec2 vTexCoord;

	void main() {
		vTexCoord = aTexCoord;

		vec4 positionVec4 = vec4(aPosition, 1.0);
		positionVec4.xy = positionVec4.xy * 2.0 - 1.0;

		gl_Position = positionVec4;
	}
`;

